            "【光鸭转存助手】【新订阅】%s 个订阅先匹配 7 天频道缓存；未覆盖部分再立即搜索观影，不单独刷新频道",
            len(ids),
        )
        self._queue_async_route_check(ids, trigger="新订阅资源匹配")


