def _cursor_snapshot_v11220(raw: Any) -> Dict[str, int]:
    result: Dict[str, int] = {}
    if not isinstance(raw, dict):
        return result
    for source, row in raw.items():
        value = row.get("last_message_id") if isinstance(row, dict) else row
        try:
            cursor = int(value or 0)
        except (TypeError, ValueError):
            cursor = 0
        result[str(source or "").strip()] = max(0, cursor)
    return result


def _channel_label_v11220(source_url: str) -> str:
    return "光鸭云盘影视热更频道" if "regeng" in str(source_url or "").lower() else "光鸭云盘资源分享频道"


def _install_channel_cursor_completeness_v11220(legacy_module: Any) -> None:
    """包住 legacy.refresh_channels：没追到旧游标就回滚游标，绝不越过未读消息。"""
    assistant_cls = getattr(legacy_module, "GuangYaTransferAssistant", None)
    current_refresh = getattr(assistant_cls, "refresh_channels", None) if assistant_cls else None
    if not callable(current_refresh) or getattr(current_refresh, "_guangya_channel_complete_v11220", False):
        return
    original_refresh = current_refresh

    @functools.wraps(original_refresh)
    def patched_refresh(self, force: bool = False):
        source_urls = list(self._source_urls() or [])
        before_raw = self.get_data("channel_cursors") or {}
        before_cursors = _cursor_snapshot_v11220(before_raw)
        catchup = self.get_data(_CHANNEL_CATCHUP_KEY_V11220) or {}
        if not isinstance(catchup, dict):
            catchup = {}
        catchup = dict(catchup)
        try:
            configured_pages = max(1, int(getattr(self, "_history_pages", 1) or 1))
        except (TypeError, ValueError):
            configured_pages = 1
        active_budgets = []
        for source_url in source_urls:
            row = catchup.get(source_url) or {}
            try:
                active_budgets.append(int((row or {}).get("page_budget") or 0))
            except (TypeError, ValueError):
                pass
        page_budget = min(
            _CHANNEL_CATCHUP_MAX_PAGES_V11220,
            max([configured_pages, *active_budgets]),
        )
        rows: List[Dict[str, Any]] = []
        incomplete: Dict[str, Dict[str, Any]] = {}
        last_index: Dict[str, Any] = {}

        for attempt in range(_CHANNEL_CATCHUP_ATTEMPTS_V11220):
            previous_limit = getattr(self, "_history_pages", configured_pages)
            self._history_pages = page_budget
            try:
                rows = list(original_refresh(self, force=bool(force or catchup or attempt > 0)) or [])
            finally:
                self._history_pages = previous_limit

            after_raw = self.get_data("channel_cursors") or {}
            after_cursors = _cursor_snapshot_v11220(after_raw)
            last_index = dict(self.get_data("channel_index") or {})
            source_status = dict(last_index.get("source_status") or {})
            incomplete = {}
            for source_url in source_urls:
                old_cursor = int(before_cursors.get(source_url, 0) or 0)
                new_cursor = int(after_cursors.get(source_url, 0) or 0)
                status = dict(source_status.get(_channel_label_v11220(source_url)) or {})
                if (
                    old_cursor > 0
                    and new_cursor > old_cursor
                    and bool(status.get("success"))
                    and not bool(status.get("reached_cursor"))
                ):
                    incomplete[source_url] = {
                        "old_cursor": old_cursor,
                        "high_watermark": new_cursor,
                        "status": status,
                    }

            if not incomplete:
                changed = False
                for source_url in source_urls:
                    status = dict(source_status.get(_channel_label_v11220(source_url)) or {})
                    if bool(status.get("success")) and source_url in catchup:
                        catchup.pop(source_url, None)
                        changed = True
                    if status and status.get("catchup_incomplete"):
                        status["catchup_incomplete"] = False
                        status["page_budget"] = page_budget
                        source_status[_channel_label_v11220(source_url)] = status
                        changed = True
                if changed:
                    catchup = {
                        key: dict(value) for key, value in catchup.items()
                        if key in set(source_urls) and isinstance(value, dict)
                    }
                    last_index["source_status"] = source_status
                    self.save_data("channel_index", last_index)
                    self.save_data(_CHANNEL_CATCHUP_KEY_V11220, catchup)
                return rows

            # legacy 已经把游标推进到当前抓取的最高 ID；在继续翻页前先恢复旧游标。
            restored_cursors = dict(after_raw) if isinstance(after_raw, dict) else {}
            for source_url, detail in incomplete.items():
                old_row = dict((before_raw or {}).get(source_url) or {}) if isinstance((before_raw or {}).get(source_url), dict) else {}
                old_row["last_message_id"] = int(detail["old_cursor"])
                restored_cursors[source_url] = old_row
            self.save_data("channel_cursors", restored_cursors)

            if attempt + 1 < _CHANNEL_CATCHUP_ATTEMPTS_V11220 and page_budget < _CHANNEL_CATCHUP_MAX_PAGES_V11220:
                page_budget = min(
                    _CHANNEL_CATCHUP_MAX_PAGES_V11220,
                    max(configured_pages * 2, page_budget * 2),
                )
                continue
            break

        # 本轮有界追赶仍未触达旧游标：保留旧游标，并为下轮继续扩大预算；这是延迟，不是静默丢失。
        index = dict(self.get_data("channel_index") or last_index or {})
        source_status = dict(index.get("source_status") or {})
        next_budget = min(
            _CHANNEL_CATCHUP_MAX_PAGES_V11220,
            max(configured_pages * 2, page_budget * 2),
        )
        now_text = ""
        now_reader = getattr(self, "_now_text", None)
        if callable(now_reader):
            try:
                now_text = str(now_reader() or "")
            except Exception:
                now_text = ""
        for source_url, detail in incomplete.items():
            old_cursor = int(detail["old_cursor"])
            high_watermark = int(detail["high_watermark"])
            catchup[source_url] = {
                "last_message_id": old_cursor,
                "high_watermark": high_watermark,
                "page_budget": next_budget,
                "updated": now_text,
            }
            label = _channel_label_v11220(source_url)
            status = dict(source_status.get(label) or detail.get("status") or {})
            status.update({
                "cursor": old_cursor,
                "high_watermark": high_watermark,
                "page_budget": page_budget,
                "next_page_budget": next_budget,
                "catchup_incomplete": True,
            })
            source_status[label] = status
            self._plugin_log(
                "WARNING",
                "【光鸭转存助手】【频道完整性v1.12.20】%s 已抓到高水位 %s，但 %s 页预算仍未追到旧游标 %s；"
                "已回退游标，下一轮页预算=%s，不会越过未读取消息",
                label,
                high_watermark,
                page_budget,
                old_cursor,
                next_budget,
            )
        catchup = {
            key: dict(value) for key, value in catchup.items()
            if key in set(source_urls) and isinstance(value, dict)
        }
        index["source_status"] = source_status
        self.save_data("channel_index", index)
        self.save_data(_CHANNEL_CATCHUP_KEY_V11220, catchup)
        return rows

    patched_refresh._guangya_channel_complete_v11220 = True
    patched_refresh._guangya_original_refresh_channels = original_refresh
    assistant_cls.refresh_channels = patched_refresh


def _channel_slug_from_url(source_url: str) -> str:
    try:
        path = str(urlsplit(str(source_url or "")).path or "").strip("/")
    except ValueError:
        return str(source_url or "")[-40:]
    return path.split("/")[-1] if path else str(source_url or "")[-40:]


_CHANNEL_DECODE_MAX_CHARS = 2_000_000


def _decode_channel_blob(value: Any) -> str:
    """occurrence discovery 前规范化：HTML 实体 → \\/ / \\u002F → 有限次 unquote。"""
    current = html.unescape(str(value or ""))
    if len(current) > _CHANNEL_DECODE_MAX_CHARS:
        current = current[:_CHANNEL_DECODE_MAX_CHARS]
    current = current.replace("\\/", "/").replace("\\u002F", "/").replace("\\u002f", "/")
    for _ in range(3):
        decoded = unquote(current)
        if decoded == current:
            break
        current = decoded
        if len(current) > _CHANNEL_DECODE_MAX_CHARS:
            current = current[:_CHANNEL_DECODE_MAX_CHARS]
            break
    return current


def _external_sources_from_context(context_html: str) -> List[Dict[str, Any]]:
    # 先整段 decode，再 finditer；属性值同样先 decode
    raw = str(context_html or "")
    decoded = _decode_channel_blob(raw)
    attr_bits = []
    for matched in _ATTR_URL_RE.finditer(raw):
        attr_bits.append(_decode_channel_blob(matched.group(2)))
    if attr_bits:
        decoded = decoded + "\n" + "\n".join(attr_bits)
    rows: List[Dict[str, Any]] = []
    seen = set()
    matches = [(item.start(), item.group(0)) for item in _MAGNET_RE.finditer(decoded)]
    matches.extend((item.start(), item.group(0)) for item in _ED2K_RE.finditer(decoded))
    matches.sort(key=lambda pair: pair[0])
    for _, raw in matches:
        uri = _clean_external_uri(raw)
        try:
            normalized = normalize_source_uri(uri)
        except Exception:
            continue
        key = f"{normalized.get('type')}:{normalized.get('identity')}"
        if key in seen:
            continue
        seen.add(key)
        rows.append({
            "type": str(normalized.get("type") or ""),
            "uri": uri,
            "identity": str(normalized.get("identity") or ""),
            "name": str(normalized.get("name") or "")[:300],
            "size": int(normalized.get("size") or 0),
        })
    return rows


def _log_resource_discovery(legacy_module: Any, source_url: str, entry: Dict[str, Any]) -> None:
    """频道级调试日志；不打印 cookie/token。"""
    logger = getattr(legacy_module, "logger", None)
    if logger is None:
        return
    channel = _channel_slug_from_url(source_url)
    message_id = str(entry.get("message_id") or "") or "-"
    xunlei_n = len(entry.get("xunlei_sources") or [])
    guangya_n = 1 if str(entry.get("share_url") or "").strip() else 0
    magnet_n = sum(1 for item in (entry.get("external_sources") or []) if str(item.get("type") or "") == "magnet")
    ed2k_n = sum(1 for item in (entry.get("external_sources") or []) if str(item.get("type") or "") == "ed2k")
    try:
        logger.info(
            "【光鸭转存助手】【频道】channel=%s message_id=%s",
            channel,
            message_id,
        )
        logger.info(
            "【光鸭转存助手】【资源发现】xunlei=%s guangya=%s magnet=%s ed2k=%s",
            xunlei_n,
            guangya_n,
            magnet_n,
            ed2k_n,
        )
        title = str(entry.get("display_title") or entry.get("title") or "")[:120]
        if title or entry.get("episode_hint"):
            logger.info(
                "【光鸭转存助手】【媒体匹配】title=%s season=%s episodes=%s",
                title or "-",
                entry.get("season_hint") or entry.get("season") or "-",
                entry.get("episode_hint") or "-",
            )
    except Exception:
        return


def install_channel_multisource_compat(legacy_module: Any):
    """热重载安全地扩展频道解析器、消息稳定键和 v1.12.20 完整性补丁。"""
    _install_channel_title_compat_v11220(legacy_module)
    _install_channel_cursor_completeness_v11220(legacy_module)
    assistant_cls = getattr(legacy_module, "GuangYaTransferAssistant", None)
    current_source_urls = getattr(assistant_cls, "_source_urls", None) if assistant_cls else None
    if callable(current_source_urls) and not getattr(current_source_urls, "_guangya_source_urls_v11221", False):
        original_source_urls = current_source_urls

        @functools.wraps(original_source_urls)
        def patched_source_urls(self) -> List[str]:
            original = [str(item or "").strip() for item in (original_source_urls(self) or []) if str(item or "").strip()]
            normalized = _normalize_channel_source_urls_v11221(original, legacy_module)
            if normalized:
                return normalized
            fallbacks = [str(item or "").strip() for item in (getattr(legacy_module, "DEFAULT_CHANNEL_URLS", []) or []) if str(item or "").strip()]
            return fallbacks

        patched_source_urls._guangya_source_urls_v11221 = True
        patched_source_urls._guangya_original_source_urls = original_source_urls
        assistant_cls._source_urls = patched_source_urls

    current_extract = getattr(legacy_module, "_extract_channel_entries", None)
    current_key = getattr(legacy_module, "_entry_process_key", None)
    if not callable(current_extract) or not callable(current_key):
        return None

    if not getattr(current_key, "_guangya_resource_group_key", False):
        original_key = current_key

        @functools.wraps(original_key)
        def patched_key(entry: Dict[str, Any]) -> str:
            existing = original_key(entry)
            if existing:
                return existing
            group_id = str((entry or {}).get("resource_group_id") or "").strip()
            if not group_id:
                return ""
            return hashlib.sha256(f"resource-group|{group_id}".encode("utf-8")).hexdigest()

        patched_key._guangya_resource_group_key = True
        patched_key._guangya_original_entry_process_key = original_key
        legacy_module._entry_process_key = patched_key

    current_extract = getattr(legacy_module, "_extract_channel_entries", None)
    if getattr(current_extract, "_guangya_channel_multisource", False):
        return current_extract
    original_extract = current_extract

    @functools.wraps(original_extract)
    def patched_extract(page_text: str, source_url: str, source_label: str) -> List[Dict[str, Any]]:
        base_entries = list(original_extract(page_text, source_url, source_label) or [])
        # 必须在 Magnet/ED2K occurrence discovery 之前完成 URL decode
        decoded = _decode_channel_blob(page_text)
        occurrence_positions = [item.start() for item in _MAGNET_RE.finditer(decoded)]
        occurrence_positions.extend(item.start() for item in _ED2K_RE.finditer(decoded))

        groups: Dict[str, Dict[str, Any]] = {}
        for position in sorted(set(occurrence_positions)):
            context_html = legacy_module._message_context_html(decoded, position)
            context = legacy_module._html_to_text(context_html)
            external = _external_sources_from_context(context_html)
            if not external:
                continue
            metadata = dict(legacy_module._entry_metadata(context, context_html) or {})
            metadata["episode_hint"] = _better_episode_hint(context, metadata.get("episode_hint"))
            message_id = str(metadata.get("message_id") or "")
            group_id = _resource_group_id(source_url, message_id, context)
            row = groups.get(group_id)
            if row is None:
                row = {
                    "resource_group_id": group_id,
                    "text": context[:4000],
                    "source_url": source_url,
                    "source_label": source_label,
                    "priority": 0 if "regeng" in source_url.lower() else 1,
                    "stale": False,
                    "cached_index": False,
                    "external_sources": [],
                    **metadata,
                }
                groups[group_id] = row
            seen = {f"{item.get('type')}:{item.get('identity')}" for item in row["external_sources"]}
            for item in external:
                key = f"{item.get('type')}:{item.get('identity')}"
                if key not in seen:
                    seen.add(key)
                    row["external_sources"].append(item)

        attached_groups = set()
        for entry in base_entries:
            entry["episode_hint"] = _better_episode_hint(entry.get("text"), entry.get("episode_hint"))
            message_id = str(entry.get("message_id") or "")
            candidates = []
            for group_id, group in groups.items():
                same_message = bool(message_id and message_id == str(group.get("message_id") or ""))
                if not same_message and not message_id and str(entry.get("text") or "") == str(group.get("text") or ""):
                    same_message = True
                if not same_message:
                    continue
                entry["resource_group_id"] = group_id
                entry["external_sources"] = list(group.get("external_sources") or [])
                entry["candidate_types"] = ["guangya", *[str(item.get("type") or "") for item in entry["external_sources"]]]
                attached_groups.add(group_id)
                candidates = entry["external_sources"]
                break
            if not candidates:
                group_id = _resource_group_id(source_url, message_id, str(entry.get("text") or ""))
                entry["resource_group_id"] = group_id
                entry.setdefault("external_sources", [])
                entry["candidate_types"] = ["guangya"]

        for group_id, group in groups.items():
            if group_id in attached_groups:
                continue
            pseudo = {
                **group,
                "share_url": "",
                "share_id": "",
                "link_style": "外部资源",
                "candidate_types": [str(item.get("type") or "") for item in group.get("external_sources") or []],
            }
            base_entries.append(pseudo)

        for entry in base_entries:
            if entry.get("external_sources") or entry.get("share_url") or entry.get("xunlei_sources"):
                _log_resource_discovery(legacy_module, source_url, entry)

        return base_entries

    patched_extract._guangya_channel_multisource = True
    patched_extract._guangya_original_extract_channel_entries = original_extract
    legacy_module._extract_channel_entries = patched_extract
    return patched_extract


__all__ = [
    "install_channel_multisource_compat",
]

channel_title_rename_v11226:
"""v1.12.26 频道标题清洗 + 转存后「剧集名 + 季集」命名。

1. 兼容 tgm 合集里常见的非热更模板：
   - `名称：标题(2026） 4K 更新至11集`
   - `[剧集·光鸭] 标题 (2022)`
   清理画质/更新尾巴与频道标签前缀，避免强标题匹配失败后直接跳过转存。
2. 转存落盘命名改为：`剧集名 SxxExx.ext`（多集 `SxxExx-Eyy`）；电影仅用剧名。
   覆盖迅雷秒传、Magnet/ED2K 云添加提交名，以及光鸭分享落盘后的远端 rename。
"""
from __future__ import annotations

import functools
import html
import re
from pathlib import Path
from typing import Any, Dict, Iterable, List, Optional, Tuple

from .legacy import _episode_numbers, _is_subtitle, _is_video, _safe_relative_path


_FORBIDDEN_NAME_V11226 = re.compile(r"[\\/:*?\"<>|\x00-\x1f]+")
_YEAR_TAIL_V11226 = re.compile(
    r"[（(]\s*(?:19\d{2}|20\d{2})\s*[）)].*$"
)
_BRACKET_TAG_V11226 = re.compile(r"【[^】]{0,80}】")
_HDHIVE_PREFIX_V11226 = re.compile(
    r"^\[\s*(?:剧集|电影|动漫|动画|综艺)[^\]]{0,40}\]\s*",
    re.I,
)
_QUALITY_TAIL_V11226 = re.compile(
    r"(?i)\s*(?:"
    r"4K|8K|2160p|1080p|720p|480p|HDR10\+?|DV|Dolby|Atmos|"
    r"WEB-?DL|WEBRip|BluRay|REMUX|H\.?265|H\.?264|HEVC|AAC|DDP|"
    r"更新至\s*\d+\s*集|更新到\s*\d+\s*集|更至\s*\d+\s*集|"
    r"全\s*\d+\s*集|全季|全集|剧情|奇幻|古装|喜剧|动作|爱情|"
    r"高码率|内封|简繁英"
    r").*$"
)
_HDHIVE_LINE_V11226 = re.compile(
    r"(?im)^\s*\[\s*(?:剧集|电影|动漫|动画|综艺)[^\]]{0,40}\]\s*([^\n]{2,240})\s*$"
)


def _safe_name_v11226(value: Any, limit: int = 120) -> str:
    text = _FORBIDDEN_NAME_V11226.sub(" ", str(value or ""))
    text = re.sub(r"\s+", " ", text).strip(" .-_")
    return text[: max(1, int(limit or 120))].strip()


def _show_name_v11226(subscribe: Any) -> str:
    raw = str(getattr(subscribe, "name", "") or "").strip()
    raw = re.sub(r"\s*[（(]\s*(?:19\d{2}|20\d{2})\s*[）)]\s*$", "", raw).strip()
    return _safe_name_v11226(raw)


def _split_name_ext_v11226(name: Any) -> Tuple[str, str]:
    text = str(name or "").replace("\\", "/").rsplit("/", 1)[-1].strip()
    if not text:
        return "", ""
    path = Path(text)
    suffix = path.suffix
    if suffix and len(suffix) <= 8:
        return path.stem, suffix
    return text, ""


def _episode_tag_v11226(subscribe: Any, path: Any) -> str:
    """生成 SxxExx / SxxExx-Eyy；无法解析集号时仅返回季号或空串。"""
    season, episodes = _episode_numbers(path)
    sub_season = getattr(subscribe, "season", None)
    if season is None and sub_season not in (None, ""):
        try:
            season = int(sub_season)
        except (TypeError, ValueError):
            season = None
    if not episodes:
        if season is None:
            return ""
        return f"S{int(season):02d}"
    values = sorted({int(ep) for ep in episodes if int(ep) > 0})
    if not values:
        return ""
    if season is None:
        season = 1
    if len(values) == 1:
        return f"S{int(season):02d}E{values[0]:02d}"
    return f"S{int(season):02d}E{values[0]:02d}-E{values[-1]:02d}"


def _canonical_transfer_name_v11226(
    subscribe: Any,
    original: Any,
    *,
    is_movie: bool = False,
) -> str:
    """剧集名 + 季集号 + 原扩展名；无法解析集号时仅用剧集名。"""
    show = _show_name_v11226(subscribe)
    _, ext = _split_name_ext_v11226(original)
    if not show:
        base = str(original or "").replace("\\", "/").rsplit("/", 1)[-1].strip()
        return _safe_name_v11226(base, 240)
    if is_movie:
        return f"{show}{ext}"
    tag = _episode_tag_v11226(subscribe, original)
    if tag:
        return f"{show} {tag}{ext}"
    return f"{show}{ext}"


def _clean_channel_title_v11226(value: Any) -> str:
    """剥离频道模板噪声，只保留可强匹配的作品标题。"""
    title = html.unescape(str(value or "")).strip()
    title = re.sub(r"^[\s🎬🎞🎥📺]+", "", title).strip()
    title = re.sub(r"^(?:电影|剧集|电视剧|动漫|动画)\s*[：:]\s*", "", title, flags=re.I).strip()
    title = _HDHIVE_PREFIX_V11226.sub("", title).strip()
    title = _BRACKET_TAG_V11226.sub(" ", title)
    title = re.sub(r"\s+", " ", title).strip()
    # 年份后的画质/更新尾巴一律丢掉，再去掉年份本身（匹配键不需要年份）。
    if _YEAR_TAIL_V11226.search(title):
        title = _YEAR_TAIL_V11226.sub("", title).strip()
    else:
        title = _QUALITY_TAIL_V11226.sub("", title).strip()
    title = re.sub(r"\s*(?:已?更新|更新中|已?完结|完结|全集|全季)\s*$", "", title, flags=re.I).strip()
    return title[:300]


def _extract_channel_title_v11226(raw: Any, fallback) -> str:
    text = str(raw or "")
    labelled = re.search(r"(?im)(?:^|\n)\s*(?:名称|片名|剧名|标题)\s*[：:]\s*([^\n]{2,320})", text)
    if labelled:
        cleaned = _clean_channel_title_v11226(labelled.group(1))
        if cleaned:
            return cleaned
    hdhive = _HDHIVE_LINE_V11226.search(text)
    if hdhive:
        cleaned = _clean_channel_title_v11226(hdhive.group(1))
        if cleaned:
            return cleaned
    cleaned = _clean_channel_title_v11226(fallback(text) if callable(fallback) else "")
    if cleaned:
        return cleaned
    return _clean_channel_title_v11226(text)


def install_channel_title_rename_v11226(legacy_module: Any) -> None:
    """热重载安全地增强频道标题解析，不改动分享链接识别。"""
    current_clean = getattr(legacy_module, "_clean_channel_display_title", None)
    current_extract = getattr(legacy_module, "_extract_channel_display_title", None)
    if not callable(current_clean) or not callable(current_extract):
        return
    if getattr(current_extract, "_guangya_channel_title_v11226", False):
        return

    original_clean = current_clean
    original_extract = current_extract

    @functools.wraps(original_clean)
    def patched_clean(value: Any) -> str:
        cleaned = _clean_channel_title_v11226(original_clean(value))
        return cleaned or _clean_channel_title_v11226(value)

    @functools.wraps(original_extract)
    def patched_extract(value: Any) -> str:
        return _extract_channel_title_v11226(value, original_extract)

    patched_extract._guangya_channel_title_v11226 = True
    patched_extract._guangya_original_extract_channel_title = original_extract
    legacy_module._clean_channel_display_title = patched_clean
    legacy_module._extract_channel_display_title = patched_extract


class GuangYaChannelTitleRenameV11226Mixin:
    """频道标题兼容 + 转存文件名改为剧集名+季集。"""

    plugin_version = "1.12.26"
    build_id = "20260910-r73"

    def _is_movie_for_naming_v11226(self, subscribe: Any) -> bool:
        checker = getattr(self, "_is_movie_subscription", None)
        if callable(checker):
            try:
                return bool(checker(subscribe))
            except Exception:
                return False
        media_type = str(getattr(subscribe, "type", "") or getattr(subscribe, "media_type", "") or "").lower()
        return media_type in {"movie", "movies", "电影"}

    def _canonical_transfer_name_v11226(self, subscribe: Any, original: Any) -> str:
        return _canonical_transfer_name_v11226(
            subscribe,
            original,
            is_movie=self._is_movie_for_naming_v11226(subscribe),
        )

    def _resolve_offline_source(self, source: Dict[str, Any], subscribe: Any) -> Dict[str, Any]:
        resolved = dict(super()._resolve_offline_source(source, subscribe) or {})
        original = str(
            source.get("original_resolved_name")
            or resolved.get("resolved_name")
            or source.get("resolved_name")
            or source.get("name")
            or source.get("label")
            or ""
        ).strip()
        hint = " ".join(
            str(part or "")
            for part in (
                original,
                source.get("episode_hint"),
                source.get("label"),
                ",".join(str(v) for v in (source.get("resolved_episodes") or [])),
                ",".join(str(v) for v in (source.get("transfer_episodes") or [])),
            )
        )
        desired = self._canonical_transfer_name_v11226(subscribe, hint or original)
        if desired and desired != str(source.get("label") or ""):
            source["label"] = desired
            source_id = str(source.get("id") or "")
            if source_id:
                self._update_source(
                    source_id,
                    requested_name=desired,
                    original_resolved_name=original[:300],
                    naming_style_v11226="show_season_episode",
                )
            self._plugin_log(
                "INFO",
                "【光鸭转存助手】【命名v1.12.26】云添加名称：原名=%s 新名=%s",
                original[:180] or "-",
                desired[:220],
            )
        return resolved

    def _rapid_transfer_xunlei_file(self, subscribe: Any, row: Dict[str, Any]) -> Dict[str, Any]:
        prepared = dict(row or {})
        old_name = str(prepared.get("name") or str(prepared.get("path") or "").rsplit("/", 1)[-1] or "file").strip()
        path_hint = str(prepared.get("path") or old_name)
        desired = self._canonical_transfer_name_v11226(subscribe, path_hint)
        if desired and desired != old_name:
            prepared["name"] = desired
            raw_path = str(prepared.get("path") or old_name).replace("\\", "/")
            parent = raw_path.rsplit("/", 1)[0] if "/" in raw_path else ""
            prepared["path"] = f"{parent}/{desired}" if parent else desired
            self._plugin_log(
                "INFO",
                "【光鸭转存助手】【命名v1.12.26】迅雷秒传名称：%s -> %s",
                old_name[:180],
                desired[:220],
            )
        # 跳过 v1.12.24 的“识别文件夹前缀”，避免叠成“目录 - 剧集名 SxxExx”。
        from .auto_recovery_v11224 import GuangYaAutoRecoveryV11224Mixin

        parent = super(GuangYaAutoRecoveryV11224Mixin, self)
        return dict(parent._rapid_transfer_xunlei_file(subscribe, prepared) or {})

    def _rename_restored_media_v11224(
        self,
        subscribe: Any,
        save_path: str,
        items: Iterable[Dict[str, Any]],
    ) -> int:
        """覆盖 v1.12.24 前缀命名：落盘后改为剧集名 + 季集。"""
        if subscribe is None:
            return 0
        client, api = self._get_guangya_runtime()
        if not client or not api or not callable(getattr(client, "rename", None)):
            return 0
        groups: Dict[str, List[Dict[str, Any]]] = {}
        for item in items or []:
            path = str(item.get("effective_path") or item.get("relative_path") or item.get("name") or "")
            if not (_is_video(path) or _is_subtitle(path)):
                continue
            groups.setdefault(str(item.get("target_parent") or ""), []).append(dict(item))
        renamed = 0
        base = str(save_path or "/").replace("\\", "/").rstrip("/") or "/"
        rename_ok = getattr(self, "_rename_ok_v11224", None)
        for relative_parent, group in groups.items():
            parent = _safe_relative_path(relative_parent)
            folder_path = (base.rstrip("/") + ("/" + parent if parent else "")) or "/"
            try:
                folder = api.get_item(Path(folder_path)) if callable(getattr(api, "get_item", None)) else None
                if folder is None:
                    continue
                remote_rows = list(api.list(folder) or []) if callable(getattr(api, "list", None)) else []
            except Exception as err:
                self._plugin_log(
                    "WARNING",
                    "【光鸭转存助手】【命名v1.12.26】读取已转存目录失败：%s (%s)",
                    folder_path,
                    str(err)[:180],
                )
                continue
            remote_by_name = {str(getattr(row, "name", "") or ""): row for row in remote_rows}
            used_names = set(remote_by_name.keys())
            for item in group:
                path = str(item.get("effective_path") or item.get("relative_path") or item.get("name") or "").replace("\\", "/")
                old_name = path.rsplit("/", 1)[-1]
                desired = self._canonical_transfer_name_v11226(subscribe, path)
                if not desired or desired == old_name:
                    continue
                if desired in used_names and desired != old_name:
                    stem, ext = _split_name_ext_v11226(desired)
                    index = 2
                    candidate = desired
                    while candidate in used_names:
                        candidate = f"{stem} ({index}){ext}"
                        index += 1
                    desired = candidate
                remote = remote_by_name.get(old_name)
                file_id = str(getattr(remote, "fileid", "") or "") if remote is not None else ""
                if not file_id:
                    continue
                try:
                    response = client.rename(file_id, desired)
                    ok = bool(rename_ok(response)) if callable(rename_ok) else True
                    if ok:
                        renamed += 1
                        used_names.discard(old_name)
                        used_names.add(desired)
                        self._plugin_log(
                            "INFO",
                            "【光鸭转存助手】【命名v1.12.26】分享落盘后重命名：%s -> %s",
                            old_name[:180],
                            desired[:220],
                        )
                    else:
                        self._plugin_log(
                            "WARNING",
                            "【光鸭转存助手】【命名v1.12.26】分享已成功但重命名未确认：%s -> %s",
                            old_name[:160],
                            desired[:200],
                        )
                except Exception as err:
                    self._plugin_log(
                        "WARNING",
                        "【光鸭转存助手】【命名v1.12.26】分享已成功但重命名异常：%s",
                        str(err)[:220],
                    )
        return renamed


__all__ = [
    "GuangYaChannelTitleRenameV11226Mixin",
    "install_channel_title_rename_v11226",
    "_canonical_transfer_name_v11226",
    "_clean_channel_title_v11226",
]

channel_ui_v1101:
"""v1.10.1 频道资源与配置页补全。

v1.10.0 重做首页时保留了频道索引计数，却误把频道资源明细从控制台裁掉；同时频道源虽然
仍存在于配置模型中，但和外部 Magnet/ED2K 接口挤在同一张“资源来源”卡片里，实际使用时
很容易被误认为配置入口已经消失。本层把频道资源重新提升为一等功能：

- 首页独立展示频道索引、来源、TMDB/集数和 ResourceGroup 可用方式；
- 配置页恢复独立“频道资源”卡片，频道地址与刷新/抓取参数集中管理；
- 提供只读 `/channels/resources` API，公开数据不返回光鸭分享 URL、Magnet/ED2K 原始 URI；
- 不改变频道抓取、资源匹配和自动转存业务逻辑。
"""

from __future__ import annotations

from copy import deepcopy
from typing import Any, Dict, Iterable, List, Set


class GuangYaChannelUiV1101Mixin:
    """恢复频道资源可见性，并让频道配置在 MoviePilot 配置页中明确可见。"""

    build_id = "20260901-r12"

    @staticmethod
    def _channel_model(node: Any, model: str) -> bool:
        if isinstance(node, dict):
            props = node.get("props")
            if isinstance(props, dict) and str(props.get("model") or "") == model:
                return True
            return any(GuangYaChannelUiV1101Mixin._channel_model(value, model) for value in node.values())
        if isinstance(node, list):
            return any(GuangYaChannelUiV1101Mixin._channel_model(value, model) for value in node)
        return False

    @classmethod
    def _strip_channel_model_cols(cls, node: Any, models: Set[str]) -> Any:
        """从 v1.10.0 其它卡片移除重复频道控件，避免同一个 model 在表单出现两次。"""
        if isinstance(node, list):
            cleaned: List[Any] = []
            for value in node:
                if (
                    isinstance(value, dict)
                    and str(value.get("component") or "") == "VCol"
                    and any(cls._channel_model(value, model) for model in models)
                ):
                    continue
                transformed = cls._strip_channel_model_cols(value, models)
                if (
                    isinstance(transformed, dict)
                    and str(transformed.get("component") or "") == "VRow"
                    and not list(transformed.get("content") or [])
                ):
                    continue
                cleaned.append(transformed)
            return cleaned
        if isinstance(node, dict):
            result = dict(node)
            for key, value in list(result.items()):
                if isinstance(value, (dict, list)):
                    result[key] = cls._strip_channel_model_cols(value, models)
            return result
        return node

    @staticmethod
    def _replace_text(node: Any, old: str, new: str) -> None:
        if isinstance(node, dict):
            if str(node.get("text") or "") == old:
                node["text"] = new
            for value in node.values():
                GuangYaChannelUiV1101Mixin._replace_text(value, old, new)
        elif isinstance(node, list):
            for value in node:
                GuangYaChannelUiV1101Mixin._replace_text(value, old, new)

    def _configured_channel_count_v1101(self) -> int:
        try:
            urls = list(self._source_urls() or [])
            if urls:
                return len(urls)
        except Exception:
            pass
        raw = str(getattr(self, "_channel_urls", "") or "")
        return len([line for line in raw.splitlines() if line.strip()])

    @staticmethod
    def _candidate_text(entry: Dict[str, Any]) -> str:
        raw: Iterable[Any] = entry.get("candidate_types") or []
        labels = []
        mapping = {"guangya": "光鸭", "magnet": "Magnet", "ed2k": "ED2K", "xunlei": "迅雷"}
        for item in raw:
            key = str(item or "").strip().lower()
            label = mapping.get(key, key.upper())
            if label and label not in labels:
                labels.append(label)
        if not labels and entry.get("share_url"):
            labels.append("光鸭")
        return " / ".join(labels) or "-"

    @staticmethod
    def _channel_title(entry: Dict[str, Any]) -> str:
        title = str(entry.get("display_title") or entry.get("resolved_name") or "").strip()
        if title:
            return title[:160]
        text = str(entry.get("text") or "").strip()
        if text:
            for line in text.splitlines():
                line = line.strip()
                if line:
                    return line[:160]
        return "未命名频道资源"

    def _public_channel_resources_v1101(self, *, limit: int = 60) -> Dict[str, Any]:
        index = self.get_data("channel_index") or {}
        raw_items = list(index.get("items") or []) if isinstance(index, dict) else []
        rows: List[Dict[str, Any]] = []
        for entry in raw_items[: max(1, int(limit or 60))]:
            if not isinstance(entry, dict):
                continue
            rows.append({
                "title": self._channel_title(entry),
                "tmdb_id": str(entry.get("tmdb_id") or ""),
                "episode": str(entry.get("episode_hint") or entry.get("total_episode_hint") or ""),
                "source": str(entry.get("source_label") or "频道")[:120],
                "message_id": str(entry.get("message_id") or "")[:80],
                "candidates": self._candidate_text(entry),
                "stale": bool(entry.get("stale")),
                "cached": bool(entry.get("cached_index")),
            })
        errors = []
        for raw in list(index.get("errors") or [])[:8] if isinstance(index, dict) else []:
            if isinstance(raw, dict):
                errors.append(str(raw.get("error") or raw.get("message") or raw.get("source") or "频道抓取异常")[:240])
            else:
                errors.append(str(raw)[:240])
        return {
            "success": True,
            "message": f"频道索引 {len(raw_items)} 条",
            "count": len(raw_items),
            "configured_sources": self._configured_channel_count_v1101(),
            "updated_at": str(index.get("time") or "-") if isinstance(index, dict) else "-",
            "errors": errors,
            "items": rows,
        }

    def api_channel_resources(self) -> Dict[str, Any]:
        """返回脱敏后的频道索引，用于页面和排障。"""
        return self._public_channel_resources_v1101(limit=100)

    def get_api(self):
        apis = list(super().get_api() or [])
        if not any(str(item.get("path") or "") == "/channels/resources" for item in apis if isinstance(item, dict)):
            apis.append({
                "path": "/channels/resources",
                "endpoint": self.api_channel_resources,
                "methods": ["GET"],
                "summary": "读取脱敏后的频道资源索引",
            })
        return apis

    def _channel_page_card_v1101(self) -> Dict[str, Any]:
        report = self._public_channel_resources_v1101(limit=24)
        rows = list(report.get("items") or [])
        content: List[Dict[str, Any]] = []

        if report.get("errors"):
            content.append({
                "component": "VAlert",
                "props": {
                    "type": "warning",
                    "variant": "tonal",
                    "density": "compact",
                    "class": "mb-3",
                    "style": "border-radius:14px;",
                    "text": "；".join(list(report.get("errors") or [])[:3]),
                },
            })

        if rows:
            content.append({
                "component": "VDataTable",
                "props": {
                    "density": "compact",
                    "items-per-page": 10,
                    "headers": [
                        {"title": "频道资源", "key": "title"},
                        {"title": "TMDB", "key": "tmdb_id"},
                        {"title": "集数", "key": "episode"},
                        {"title": "来源", "key": "source"},
                        {"title": "可用方式", "key": "candidates"},
                        {"title": "状态", "key": "state"},
                    ],
                    "items": [
                        {
                            **row,
                            "state": "缓存" if row.get("cached") else ("过期" if row.get("stale") else "可用"),
                        }
                        for row in rows
                    ],
                    "style": "border-radius:14px;overflow:hidden;",
                },
            })
        else:
            content.append({
                "component": "VAlert",
                "props": {
                    "type": "info",
                    "variant": "tonal",
